contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        uint256 beforeBal = c.balances(address(this));
        bool overflow = amount > type(uint256).max - beforeBal;

        bool reverted;
        if (overflow) {
            // A transfer whose sum overflows must revert, and must not change the balance.
            try c.Deposit{value: 0}() {
                reverted = false;
            } catch {
                reverted = true;
            }
            // Since Deposit is called with 0 value here, the overflow test above is not
            // actually exercised by value; use it only as a precondition guard instead.
        }

        // Drive Deposit with the parameter amount; require the test contract holds enough Ether.
        require(address(this).balance >= amount);
        uint256 balBeforeCall = c.balances(address(this));
        bool callReverted;
        try c.Deposit{value: amount}() {
            callReverted = false;
        } catch {
            callReverted = true;
        }
        uint256 balAfterCall = c.balances(address(this));

        // General rule: the caller's balance increases by exactly the sent amount on success;
        // on failure the balance is unchanged. Because Solidity reverts on overflow, a call
        // whose (balance + amount) overflows must revert and leave the balance unchanged.
        assert(
            (callReverted && balAfterCall == balBeforeCall) ||
            (!callReverted && balAfterCall == balBeforeCall + amount)
        );
    }

    receive() external payable {}
}

