        c = _c;
    }

    function run(address other, uint256 amount) public payable {
        require(address(this).balance >= amount);

        uint256 otherBefore = c.balances(other);
        uint256 selfBefore = c.balances(address(this));

        c.Deposit{value: amount}();

        uint256 otherAfter = c.balances(other);
        uint256 selfAfter = c.balances(address(this));

        assert(otherAfter == otherBefore);
    }

    receive() external payable {}
}
